import{_ as a,o as t,c as n,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"H2R: A Human-to-Robot Data Augmentation for Robot Pre-training from Videos","description":"","frontmatter":{"title":"H2R: A Human-to-Robot Data Augmentation for Robot Pre-training from Videos","arxiv":"2505.11920","date":"2025-05-17","authors":"Guangrun Li, Yaoxu Lyu, Zhuoyang Liu, Chengkai Hou, Jieyu Zhang, Shanghang Zhang","categories":"cs.RO","topics":"人类视频预训练, 数据增强, 视觉表征","outline":[2,2]},"headers":[],"relativePath":"papers/2505.11920.md","filePath":"papers/2505.11920.md","lastUpdated":null}'),e={name:"papers/2505.11920.md"};function l(i,s,r,m,o,c){return t(),n("div",null,[...s[0]||(s[0]=[p('<h1 id="h2r-a-human-to-robot-data-augmentation-for-robot-pre-training-from-videos" tabindex="-1">H2R: A Human-to-Robot Data Augmentation for Robot Pre-training from Videos <a class="header-anchor" href="#h2r-a-human-to-robot-data-augmentation-for-robot-pre-training-from-videos" aria-label="Permalink to &quot;H2R: A Human-to-Robot Data Augmentation for Robot Pre-training from Videos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.11920" target="_blank" rel="noreferrer">2505.11920</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-17</td></tr><tr><td><strong>作者</strong></td><td>Guangrun Li, Yaoxu Lyu, Zhuoyang Liu, Chengkai Hou, Jieyu Zhang, Shanghang Zhang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用 HaMeR 估计第一人称视频里的手部位姿并重定向到仿真机械臂，再用 SAM+LaMa 抹掉人手、按相机内外参对齐把渲染的机器人贴回原帧，从而在预训练阶段就消除人-机表观差距。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v4</strong>（2026-03-16 修订）撰写。v1 提交于 2025-05-17，v4 大幅扩充了仿真基准（新增 CortexBench）、跨本体实验、光照鲁棒性与 UVA 集成实验，并新增了 CLIP 数据质量评估。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人演示数据昂贵，用现成的第一人称人类视频（Ego4D、SSv2、EPIC-Kitchens）做视觉表征预训练已经被 R3M、MVP、Voltron 等工作证明可行。但这些数据集本质上是<strong>以人为中心</strong>的：画面里操作物体的是一双人手，而部署时画面里是一只机械臂。这个表观差距在预训练阶段完全没有被处理——编码器学到的&quot;抓握中的前景&quot;是肉色的、五指的、柔软的，而下游看到的是金属的、两指或多指刚性的。作者要问的是：如果在预训练<strong>之前</strong>就把人手换成机器人，表征迁移会不会更好。</p><p>价值在于它落在一条正确的杠杆上：不改架构、不改损失、不需要额外标注，只改数据。任何用人类视频做预训练的流水线都可以直接套用。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>跨域视觉对齐已有几条路线。WHIRL 从第三人称视角匹配任务结构，但不处理像素级表观。RoVi-Aug 与 Mirage 通过分割或图像空间预处理来改变外观——它们主要作用在<strong>机器人数据</strong>上（把一种机器人变成另一种），而不是把人变成机器人。EgoMimic 会移除手部并归一化视角，但移除之后留下的是空白：手-物交互发生的那片像素被抹掉了，而那正是信息最密集的区域。</p><p>表征预训练侧，R3M、MVP、Voltron、VC-1 各自在目标函数与数据构成上做文章，默认接受&quot;人类视频就是人类视频&quot;这一前提。所以缺口不是&quot;没人想过换手&quot;，而是：换手需要同时解决三件事——手部 3D 位姿估计要够准（否则机器人贴错位置）、抹除要干净（否则残留人手轮廓）、渲染要与原图相机对齐（否则透视不一致）。三者在 2023 年之前都不够成熟；HaMeR、SAM、LaMa 的出现才让这条流水线在工程上可行。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有的失败模式很具体：在人类视频上预训练的编码器，下游微调时对夹爪区域的响应并不稳定。一个自然的假设是这源于前景外观的分布不匹配。要验证它，最直接的干预就是把前景换掉。</p><p>但&quot;换掉&quot;有强弱两个版本。弱版本是 EgoMimic 式的——把手抹掉就完事，让模型只看背景与物体。这个版本有个可预测的问题：手-物接触点承载了任务的绝大部分信息，抹掉等于删掉了标签。强版本是把手换成机器人，既保留&quot;有东西在这里操作&quot;的信号，又让这个东西长得像部署时会看到的样子。要做强版本，就必须回答&quot;机器人应该摆成什么姿势、放在哪个像素&quot;——而 HaMeR 恰好同时输出手部关键点<strong>和</strong>相机内外参，这两样东西正好够用：关键点决定末端执行器的开合与指关节角度，相机参数决定仿真里的虚拟相机该放在哪，从而使渲染出的机器人与原图共享同一个透视。这条推理链解释了为什么整个方法必须建立在 3D 手部重建之上，而不是简单的 2D 手部检测。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>人类视频里最有价值的是&quot;手在做什么&quot;，最有害的是&quot;手长什么样&quot;。把手的运动保留、把手的外观替换成机器人，就能让编码器在预训练阶段学到与部署时同分布的前景表观，而不损失任务语义。抹掉手不行——那会连运动信息一起删掉；随便贴一个机器人也不行——透视不对就成了新的伪影。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><ul><li><strong>第一步，手部位姿估计</strong>：HaMeR 在每帧上给出手的位置、3D 关键点，以及相机内参与外参。位置用于第三步分割，关键点与相机参数用于第二步。</li><li><strong>第二步，重定向</strong>：灵巧手按每根手指上连续三个关键点算出关节角；夹爪则按对应指尖之间的欧氏距离决定开合程度。手部关键点不含手臂信息，因此其余臂关节被<strong>人工设成一组合理值</strong>，凑出一个可信的机器人构型。相机对齐是关键：设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 为与人手对齐的坐标系、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 为仿真里机械臂的坐标系，把真实相机位置变换到仿真中的对应位置<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0413em;vertical-align:-0.15em;"></span><span class="mord"><span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span></span></span></span></span><span class="mord"><span class="mord"><span class="mord mathbf">cam</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mord mathnormal mtight">im</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.404em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord"></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mord mathbf">R</span><span class="mspace"> </span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord"></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mord mathbf">R</span><span class="mord"><span class="mord"><span class="delimsizing size1">)</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:1.054em;"><span style="top:-3.3029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mspace"> </span><span class="mord"><span class="mord"></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span></span></span></span></span><span class="mord"><span class="mord"><span class="mord mathbf">cam</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">.</span></span></span></span></span></p> 这一步保证仿真相机与真实第一人称相机看到同一个视角。</li><li><strong>第三步，抹除与修补</strong>：用 SAM 按手部位置与关键点分割出手与前臂区域，LaMa 修补留下的空洞，得到干净背景。</li><li><strong>合成</strong>：把仿真里机器人末端连杆的 3D 位置经对齐后的相机投影到像素坐标，与 HaMeR 给出的人手关键点像素坐标对齐，再把渲染的机械臂叠到修补后的图上，实现像素级对位。</li><li><strong>数据规模与本体</strong>：SSv2 取 1M 图像、Ego4D 取 117K 片段。三种本体：UR5+Robotiq 夹爪、UR5+Leaphand、Franka+Robotiq。除跨本体实验外，增强用的本体与下游平台保持一致。</li><li><strong>下游</strong>：编码器用 MAE 与 R3M 两套框架（均为 ViT-Base）。仿真评 Robomimic（BC）、RLBench（Diffusion Policy）、PushT、CortexBench 共 10 个任务；真机四个平台（UR5 夹爪、UR5+Leaphand、双臂 Franka、双臂 UR5e），策略用 DP 与 ACT，每任务 20 次 rollout。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>方法侧的形式化只有相机对齐这一式，但它承担了整条流水线的正确性。把上式读成两步复合：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1167em;vertical-align:-0.2753em;"></span><span class="mopen">(</span><span class="mord"><span class="mord"></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4247em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2753em;"><span></span></span></span></span></span></span><span class="mord mathbf">R</span><span class="mclose"><span class="mclose">)</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span></span></span></span> 把真实相机从世界系拉回到&quot;以人手为参考&quot;的局部系，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1167em;vertical-align:-0.2753em;"></span><span class="mord"><span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4247em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0576em;">S</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">W</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2753em;"><span></span></span></span></span></span></span><span class="mord mathbf">R</span></span></span></span> 再把这个局部描述推到仿真机械臂的参考系。也就是说，方法并不试图恢复真实世界的绝对尺度或绝对位姿——它只保证<strong>相机相对于操作主体的位形</strong>在两个世界里一致。这是一个明智的降维：绝对尺度从单目视频里本来就不可观测，而渲染叠加真正需要的只有相对位形。代价是这一致性完全继承 HaMeR 的估计误差，且误差没有任何后续校正环节。</p><p>数据质量评估用的是 CLIP 图文相似度：对原始人类帧构造&quot;A human is [action]&quot;、对增强帧构造&quot;A robotic arm is [action]&quot;，动作短语由 Qwen-2.5-VL 自动生成，随机抽 1000 对。报告结果是原图 28.01、增强图 29.83。这里必须指出一个方法学问题：两个数字<strong>用的是不同的文本 prompt</strong>，因此 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">29.83</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">28.01</span></span></span></span> 并不能推出&quot;语义保真度提高了&quot;。要支持该结论，缺的是两个对角格——增强图配人类 prompt、原图配机器人 prompt。缺了它们就无法排除一个平凡解释：CLIP 对&quot;A robotic arm is …&quot;这条句式在任何含机械臂的图上都给更高分。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：仿真下游有提升吗？</strong> 表 III（SSv2 预训练）：MAE 在 Robomimic 均值 58.0→68.2（MoveCan 54.0→79.5 是最大单项），PushT 59.2→64.5，RLBench 均值 3.3→13.3，CortexBench 86.7→92.0；R3M 分别是 55.0→61.3、15.0→22.0、10.0→15.0、73.3→74.7。需要注意 RLBench 这一组的绝对值极低（0%–20%），20 次试验下 5 个百分点等于 1 次成功，&quot;3.3→13.3&quot;落在个位数试验的范围内。CortexBench 上 R3M 的 Assembly 是 76.0→68.0（下降 8 点），并非全面提升。</p><p><strong>问题二：换预训练数据集还成立吗？</strong> 表 IV（Ego4D）：MAE 的 PushT +2.2、RLBench 1.7→5.0（其中 ToiletSeatDown 5.0→0.0 下降）；R3M 的 PushT 完全不动（13.6→13.6）、RLBench 6.7→11.7。趋势一致但幅度更小。</p><p><strong>问题三：比直接用机器人数据预训练如何？</strong> 表 V：R3M(SSv2) 55.0、R3M-DROID 56.7、R3M-H2R 61.3。作者据此说 H2R 是直接用机器人数据的有效替代。</p><p><strong>问题四：真机上呢？</strong> 表 VI 每任务 20 次。DP 下 MAE 的三组均值分别 +6.7 / +20.0 / +3.3，R3M +15.0 / +20.0 / +7.3；ACT 下 MAE +8.3 / +13.3 / +11.7，R3M +11.7 / +23.3 / +5.0。增益最集中在 Leaphand（灵巧手）任务上——这与方法一致：灵巧手的重定向直接用了逐指关节角，信息量最大。个别格子有回退（DP+MAE 的 CloseBox −5.0）或持平（SweepRubbish 多处 0.0）。</p><p><strong>问题五：哪一步在起作用？</strong> 表 XI（UR5-Leaphand，DP）：完整 H2R 60.0；去掉机器人叠加只做修补 30.0；不做对齐、随机粘贴 43.3。对照表 VI 的同配置基线（不增强）40.0 可以读出两个结论——<strong>只抹手不贴机器人（30.0）比什么都不做（40.0）还差</strong>，证实了 § 3 里&quot;抹掉等于删标签&quot;的判断；而随机粘贴（43.3）只比基线高 3.3，像素级对齐才是把 43.3 推到 60.0 的主力。</p><p><strong>问题六：换光照还成立吗？</strong> 表 XII 是全文最诚实的一组：在光照扰动下，MAE 的平均值 11.7 → H2R 11.7（<strong>净增益 0.0</strong>），R3M 5.0 → 8.3；必须再加仿真侧的随机光照增强（H2R+LightAug）才能到 28.3 与 13.3。</p><p><strong>其他</strong>：表 X 中 UVA 用 SSv2 微调 VAE 反而从 0.20 掉到 0.15，用 H2R 微调升到 0.35。表 VII 显示稀疏与稠密演示下增益都是 +10.0。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：H2R 用 HaMeR 估手部位姿、重定向到仿真机器人、SAM+LaMa 抹除人手、按相机对齐把渲染机械臂贴回原帧，把第一人称人类视频转成机器人视角数据。在 SSv2/Ego4D 上预训练 MAE 与 R3M，四个仿真套件平均提升 1.3–10.2 个百分点，四个真机平台提升 3.3–23.3 个百分点，灵巧手任务受益最大。消融给出清晰的因果链：只抹手不贴机器人（30.0）比不增强（40.0）更差，随机粘贴只到 43.3，像素级对齐才到 60.0。表 V 显示 H2R 增强的 SSv2（61.3）优于直接用 DROID 机器人数据预训练（56.7）。但光照扰动下 H2R 的净增益为 0.0，必须叠加光照随机化才恢复。</p><p><strong>3 句话版</strong>：人类视频里该保留的是手的运动、该替换的是手的外观。做到这一点的关键不是抹除，而是几何对齐的替换——三档消融把这条因果链拆得很干净。方法的收益对光照这类另一维分布偏移不具备迁移性。</p><p><strong>1 句话版</strong>：预训练数据里把人手替换成对齐好的机器人，比换损失函数便宜也更有效。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>把人手像素换成渲染的机器人像素，就缩小了预训练与部署之间的分布差距，而没有引入新的差距</strong>。H2R 的输出是&quot;LaMa 修补的背景 + 仿真渲染的机械臂&quot;的合成图，而部署时相机看到的是真实光照下的真实机械臂。合成图的边界、材质、阴影、运动模糊都与真实不同；如果编码器学到的是&quot;仿真渲染风格的前景&quot;，那它就是把一种分布差距换成了另一种。</p><p>论文自己提供了指向这一风险的最强证据：表 XII 中，一旦在评测时引入光照扰动，MAE 的 H2R 平均增益就变成 <strong>0.0</strong>（11.7 → 11.7，逐任务是 0.0 / +5.0 / −5.0），必须再叠加训练期的随机光照才能拉到 28.3。这说明 H2R 学到的表征至少部分绑定在渲染时的固定光照条件上。另一处旁证是本体匹配的必要性：论文明确说明，除跨本体实验外，增强本体与下游平台保持一致——若表征真的学到了&quot;这是一个操作中的刚性末端&quot;这种抽象概念，就不该对本体这么敏感。</p><p>缺的证据很具体：没有任何&quot;用真实机器人视频做同等规模预训练&quot;的上界对照（表 V 的 DROID 是不同数据源、不同视角，不构成上界），也没有报告编码器在真实机械臂图像与渲染机械臂图像上的特征距离。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做的判决实验：只用 MAE + RLBench 三任务（最便宜的一组），把 SSv2 的增强流水线跑三个版本，其余完全一致。(a) 完整 H2R；(b) <strong>占位体对照</strong>——保持第二步的相机对齐与像素定位完全不变，但把渲染的机械臂替换成一个同尺寸的纯色几何体（例如灰色圆柱 + 两块方板），即保留&quot;位置正确、时间连贯的刚性前景&quot;但去掉机器人形态；(c) 随机粘贴同一个占位体（对应 w/o Retarget）。</p><p>判据：若 (b) 的成功率与 (a) 相当（差距在 1 次试验以内），则收益来自&quot;在手的位置放一个几何对齐、时间连贯的刚性前景&quot;，与机器人形态无关——这将大幅简化流水线（不再需要仿真器与 URDF），也会推翻&quot;消除人-机表观差距&quot;的解释。若 (b) 明显低于 (a) 而高于 (c)，则形态与对齐各有贡献，论文的解释成立。这个实验不需要真机，也不需要重跑 HaMeR（可复用已有的位姿缓存）。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对数据质量评估。CLIP 那组数字（28.01 vs 29.83）比较的是<strong>两条不同的文本 prompt 在两组不同的图像上的得分</strong>，这在实验设计上不构成对照。反例做法：补齐 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 全表——{原图, H2R 图} × {&quot;A human is …&quot;, &quot;A robotic arm is …&quot;}。可预测的结果是，H2R 图在机器人 prompt 上高、在人类 prompt 上低，而原图正好相反；若两组的<strong>行差与列差量级相当</strong>，那么 29.83 反映的只是&quot;图里确实有机械臂&quot;，与&quot;动作语义是否被保留&quot;无关。真正能支撑语义保真的量应当是<strong>配对内的一致性</strong>，例如同一动作短语下 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord text"><span class="mord cjk_fallback">原图</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">H2R </span><span class="mord cjk_fallback">图</span></span><span class="mclose">)</span></span></span></span> 的图像-图像相似度，或在动作分类器上的 top-1 一致率。</p><p>第二条攻击针对消融的解读。作者把 w/o Overlay 的 −30.0 当作&quot;叠加机器人很重要&quot;的证据，但该配置（30.0）低于完全不增强的基线（40.0），说明 LaMa 修补<strong>本身是有害的</strong>。因此这个 −30.0 里混杂了两件事：修补造成的损害，与叠加带来的修复。干净的分解需要第四个配置——&quot;叠加机器人但不做修补&quot;（直接把渲染机器人盖在人手上）。若这一配置已接近 60.0，则修补步骤可以整条删掉，流水线成本立刻减半；若明显更低，才说明&quot;先删干净再贴&quot;是必要的。</p><p>第三条：真机每任务只有 20 次 rollout，1 次 = 5 个百分点。表 VI 里大量 +5.0 的格子等于 1 次成功之差，而全文的主张是&quot;consistent improvements&quot;。要支撑&quot;一致性&quot;，需要报告多个随机种子下的标准差；目前所有真机数字都是单次运行、无置信区间。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：H2R 目前必须为每一种下游本体单独跑一遍完整的渲染流水线（HaMeR → 重定向 → 抹除 → 修补 → 叠加 → 重新预训练），论文也确认&quot;除跨本体实验外，增强本体与下游平台匹配&quot;。这意味着每来一台新机器人，1M 帧的增强与整轮预训练都要重做——成本随本体数线性增长，与&quot;用免费的人类视频降低成本&quot;的初衷背道而驰。</p><p><strong>新的 framing</strong>：把本体从<strong>数据里的像素</strong>提升为<strong>模型里的条件变量</strong>。不再为每个本体生成一份数据集，而是一次生成多本体渲染，训练一个显式分解的表征：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">task</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">emb</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">emb</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由本体 embedding 条件化、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">task</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 通过跨本体一致性约束（同一段人类视频的不同本体渲染必须给出相同的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">task</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）被逼成本体无关。部署时只需给出新本体的 embedding，不必重跑渲染流水线。这同时把 H2R 的&quot;数据增强&quot;重新解释成&quot;为解耦提供多视图&quot;——多本体渲染是同一动作的多个视图，这正是对比式解耦最需要的东西，而 H2R 恰好能免费造出来。</p><p><strong>可借鉴的相邻领域</strong>：多域图像翻译里的 content/style 解耦（MUNIT 一系）、以及 hypernetwork / FiLM 式的条件化骨干；机器人侧可参考跨本体策略里用本体 token 做条件的做法。</p><p><strong>第一个实验</strong>：在 SSv2 上对同一批帧同时渲染三种本体（UR5-夹爪、UR5-Leaphand、Franka），训练一个带本体 embedding 与跨本体一致性损失的 MAE，与论文表 IX 的跨本体设置直接对比：把编码器迁到<strong>渲染时未出现过的第四种本体</strong>上，看成功率是否高于&quot;用最接近的单本体 H2R 编码器&quot;。若显著更高，说明本体应当被建模为条件而非烘焙进像素，H2R 的成本结构可以从&quot;每本体一次&quot;降到&quot;一次&quot;。</p>',48)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
